const headers = $json.headers ?? {};
const incoming = $json.body ?? $json;
const nestedPayload = incoming.payload && typeof incoming.payload === 'object' ? incoming.payload : {};
const secret = headers['x-agent-secret'] || headers['X-Agent-Secret'] || incoming.agent_secret || nestedPayload.agent_secret || '';
const expected = $env.AGENT_WEBHOOK_SECRET || '';
if (!secret || !expected || secret !== expected) {
  throw new Error('unauthorized: x-agent-secret must equal AGENT_WEBHOOK_SECRET');
}
const normalized = {...nestedPayload, ...incoming};
normalized.payload = nestedPayload.payload ?? nestedPayload;
normalized.agent_secret = secret;
normalized.mode = normalized.mode || 'dry_run';
normalized.action = normalized.action || 'run_lifecycle';
normalized.tool_results = Array.isArray(normalized.tool_results) ? normalized.tool_results : [];
normalized.desired_tools = Array.isArray(normalized.desired_tools) ? normalized.desired_tools : null;
const shouldRun = !normalized.desired_tools || normalized.desired_tools.includes('tool_content_generation');
if (!shouldRun) {
  const results = [...normalized.tool_results, {tool: 'tool_content_generation', status: 'skipped', reason: 'not selected for action'}];
  return [{json: {...normalized, tool_results: results, skipped_tool: 'tool_content_generation'}}];
}
const requestedRaw = normalized.requested_outputs || normalized.payload?.requested_outputs || ['campaign_plan','social_posts','email_copy','blog_article','image_prompts','video_scripts'];
const requested = Array.isArray(requestedRaw) ? requestedRaw : String(requestedRaw).split(',').map(v => v.trim()).filter(Boolean);
const registry = {
  campaign_plan: {label: 'Generate campaign plan'},
  social_posts: {label: 'Generate social posts'},
  email_copy: {label: 'Generate email copy'},
  blog_article: {label: 'Generate blog/article copy'},
  image_prompts: {label: 'Generate image prompts'},
  video_scripts: {label: 'Generate video scripts'}
};
const outputs = requested.map(output_type => ({json: {...normalized, output_type, dispatch_label: registry[output_type]?.label || 'Future extension tool', dispatch_registry: registry, current_stage: 'tool_content_generation'}}));
return outputs.length ? outputs : [{json: {...normalized, output_type: 'future_tool', dispatch_label: 'Future extension tool', current_stage: 'tool_content_generation'}}];

const state = $node['Normalize And Auth'].json;
if (state.skipped_tool) {
  return [{json: state}];
}
const rawText = $json.choices?.[0]?.message?.content ?? $json.body?.choices?.[0]?.message?.content ?? $json.data?.choices?.[0]?.message?.content ?? '';
let parsed;
let parseWarning = false;
let warningMessage = '';
if (state.mode === 'dry_run' && !rawText) {
  parsed = state.generated_output || state.fallback_payload || {mode: 'dry_run', output_type: state.output_type, items: []};
} else {
  try {
    parsed = typeof rawText === 'string' ? JSON.parse(rawText) : rawText;
  } catch (error) {
    parseWarning = true;
    warningMessage = error.message;
    parsed = {raw_text: rawText, parse_warning: true, output_type: state.output_type};
  }
}
return [{json: {...state, generated_output: parsed, generated_output_json: JSON.stringify(parsed || {}), raw_model_text: rawText, parse_warning: parseWarning, warning_message: warningMessage, qa_status: 'pending'}}];

