INSERT INTO content_errors (job_id, severity, error_code, error_message, recoverable, context)
SELECT NULLIF('{{$json.job_id}}','')::uuid, 'warning', 'GENERATION_PARSE_WARNING', COALESCE(NULLIF('{{$json.warning_message}}',''),'LLM response parse warning'), true, jsonb_build_object('raw_text', LEFT('{{$json.raw_model_text}}', 2000), 'workflow', '{{$json.current_stage}}')
WHERE COALESCE('{{$json.parse_warning}}','false') = 'true';

INSERT INTO content_tasks (job_id, task_type, task_key, status, input_payload, output_payload)
VALUES (NULLIF('{{$json.job_id}}','')::uuid, COALESCE('{{$json.output_type}}','future_tool'), COALESCE('{{$json.output_type}}','future_tool') || '-' || to_char(now(),'YYYYMMDDHH24MISSMS'), 'completed', jsonb_build_object('dispatch_pattern','add output_type mapping in tool_content_generation'), COALESCE(NULLIF('{{$json.generated_output_json}}',''),'{}')::jsonb);
INSERT INTO content_outputs (job_id, output_type, title, structured_data, qa_status)
VALUES (NULLIF('{{$json.job_id}}','')::uuid, COALESCE('{{$json.output_type}}','future_tool'), COALESCE('{{$json.dispatch_label}}','Generated output'), COALESCE(NULLIF('{{$json.generated_output_json}}',''),'{}')::jsonb, 'pending');
SELECT NULLIF('{{$json.job_id}}','') AS job_id, 'generated_outputs' AS status;

